package com.example.investsmart.settlement;

import java.nio.file.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.jdbc.datasource.init.ResourceDatabasePopulator;
import org.springframework.transaction.support.TransactionTemplate;
import static org.junit.jupiter.api.Assertions.*;

/** These dates/closures are synthetic; they do not assert real exchange holiday coverage. */
class SettlementCalendarTests {
    @Test void headerOnlyReleaseTemplateCannotActivateGuessedCoverage()throws Exception{
        byte[] bytes=Files.readAllBytes(Path.of("deploy/settlement-calendar.csv.example"));
        assertEquals("date,trading_open,settlement_open,note",new String(bytes,java.nio.charset.StandardCharsets.UTF_8).trim());
        assertThrows(IllegalArgumentException.class,()->ReviewedCalendar.parse(bytes,"NSE","EQUITY","https://www.nseclearing.in/review-required"));
    }
    @TempDir Path directory;
    DriverManagerDataSource source;JdbcTemplate db;SettlementCalendar calendar;TransactionTemplate tx;
    static final String CSV="date,trading_open,settlement_open,note\n2026-11-13,true,true,synthetic Friday\n2026-11-14,false,false,synthetic Saturday\n2026-11-15,false,false,synthetic Sunday\n2026-11-16,true,false,synthetic settlement-only closure\n2026-11-17,true,true,synthetic Tuesday\n";
    @BeforeEach void setup(){source=new DriverManagerDataSource("jdbc:h2:mem:calendar-"+UUID.randomUUID()+";MODE=MySQL;DB_CLOSE_DELAY=-1","sa","");db=new JdbcTemplate(source);new ResourceDatabasePopulator(new org.springframework.core.io.ClassPathResource("db/migrations/20261111_settlement_calendar.sql")).execute(source);tx=new TransactionTemplate(new DataSourceTransactionManager(source));calendar=new SettlementCalendar(db,Clock.fixed(Instant.parse("2026-11-11T05:00:00Z"),ZoneOffset.UTC));}
    ReviewedCalendar file(String csv)throws Exception{Path path=directory.resolve(UUID.randomUUID()+".csv");Files.writeString(path,csv);return ReviewedCalendar.read(path,"NSE","EQUITY","https://www.nseclearing.in/synthetic-test-only.csv");}
    String activate(ReviewedCalendar data){return tx.execute(status->calendar.activate(data,"SYNTHETIC_TEST","Reviewed synthetic dates for testing"));}
    @Test void nextSettlementUsesReviewedWorkingDatesRatherThanAddingTwentyFourHours()throws Exception{String id=activate(file(CSV));var result=calendar.next("NSE","EQUITY",LocalDate.of(2026,11,13));assertEquals("READY",result.status());assertEquals(LocalDate.of(2026,11,17),result.expectedDate());assertEquals(Instant.parse("2026-11-17T12:30:00Z"),result.simulationCutoff());assertEquals(id,result.versionId());}
    @Test void aTradingDayCanBeASettlementHolidayWithoutBlockingItsTradeDate()throws Exception{activate(file(CSV));assertEquals("READY",calendar.next("NSE","EQUITY",LocalDate.of(2026,11,16)).status());}
    @Test void missingActiveCalendarAndOutOfCoverageDatesStayPending()throws Exception{assertEquals("COVERAGE_MISSING",calendar.next("NSE","EQUITY",LocalDate.of(2026,11,13)).status());activate(file(CSV));for(LocalDate day:List.of(LocalDate.of(2026,11,12),LocalDate.of(2026,11,18))){var result=calendar.next("NSE","EQUITY",day);assertEquals("COVERAGE_MISSING",result.status());assertNull(result.expectedDate());assertNull(result.simulationCutoff());}}
    @Test void lastCoveredTradeDateCannotGuessASettlementDateBeyondCoverage()throws Exception{activate(file(CSV));var result=calendar.next("NSE","EQUITY",LocalDate.of(2026,11,17));assertEquals("COVERAGE_MISSING",result.status());assertNotNull(result.versionId());assertNull(result.expectedDate());}
    @Test void knownClosedTradeDateIsDistinctFromMissingCoverage()throws Exception{activate(file(CSV));var result=calendar.next("NSE","EQUITY",LocalDate.of(2026,11,14));assertEquals("TRADING_CLOSED",result.status());assertNull(result.simulationCutoff());}
    @Test void explicitSpecialSessionIsRespectedWithoutAssumingAllWeekendsAreClosed()throws Exception{activate(file(CSV.replace("2026-11-15,false,false","2026-11-15,true,false")));assertEquals(LocalDate.of(2026,11,17),calendar.next("NSE","EQUITY",LocalDate.of(2026,11,15)).expectedDate());}
    @Test void exchangesAndSegmentsHaveIndependentCoverage()throws Exception{activate(file(CSV));assertTrue(calendar.coverage("BSE","EQUITY").isEmpty());assertTrue(calendar.coverage("NSE","FNO").isEmpty());}
    @Test void reimportingIdenticalContentIsIdempotentAndReactivationRetainsHistory()throws Exception{var first=file(CSV);String id=activate(first);assertEquals(id,activate(first));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM settlement_calendar_audit",Integer.class));var changed=file(CSV.replace("2026-11-16,true,false","2026-11-16,true,true"));String revised=activate(changed);assertNotEquals(id,revised);assertEquals(LocalDate.of(2026,11,16),calendar.next("NSE","EQUITY",LocalDate.of(2026,11,13)).expectedDate());activate(first);assertEquals(LocalDate.of(2026,11,17),calendar.next("NSE","EQUITY",LocalDate.of(2026,11,13)).expectedDate());assertEquals(2,db.queryForObject("SELECT COUNT(*) FROM settlement_calendar_versions",Integer.class));assertEquals(10,db.queryForObject("SELECT COUNT(*) FROM settlement_calendar_days",Integer.class));assertEquals(3,db.queryForObject("SELECT COUNT(*) FROM settlement_calendar_audit",Integer.class));}
    @Test void simultaneousImportsSerializeAndCannotCreateDuplicateVersions()throws Exception{var data=file(CSV);var pool=Executors.newFixedThreadPool(2);try{var start=new CountDownLatch(1);Callable<String> task=()->{start.await();return activate(data);};var a=pool.submit(task);var b=pool.submit(task);start.countDown();assertEquals(a.get(10,TimeUnit.SECONDS),b.get(10,TimeUnit.SECONDS));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM settlement_calendar_versions",Integer.class));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM settlement_calendar_audit",Integer.class));}finally{pool.shutdownNow();}}
    @Test void failedAuditWriteRollsBackCalendarAndActivePointer()throws Exception{db.execute("DROP TABLE settlement_calendar_audit");assertThrows(RuntimeException.class,()->activate(file(CSV)));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM settlement_calendar_versions",Integer.class));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM settlement_calendar_active",Integer.class));}
    @Test void calendarMigrationCanBeReplayedWithoutChangingExistingAccountData(){db.execute("CREATE TABLE users(id BIGINT PRIMARY KEY,virtual_balance DECIMAL(19,2))");db.update("INSERT INTO users VALUES(1,1234.56)");new ResourceDatabasePopulator(new org.springframework.core.io.ClassPathResource("db/migrations/20261111_settlement_calendar.sql")).execute(source);assertEquals(new java.math.BigDecimal("1234.56"),db.queryForObject("SELECT virtual_balance FROM users WHERE id=1",java.math.BigDecimal.class));}
    @Test void missingAndDuplicateDatesAreRejected()throws Exception{for(String invalid:List.of(CSV.replace("2026-11-14,false,false,synthetic Saturday\n",""),CSV+"2026-11-13,true,true,duplicate\n"))assertThrows(IllegalArgumentException.class,()->file(invalid));}
    @Test void invalidFlagsDatesAndQuotedRowsFailWithoutEchoingSourceValues(){for(String invalid:List.of(CSV.replace("2026-11-13,true,true","private-value,true,true"),CSV.replace("2026-11-13,true,true","2026-11-13,yes,true"),CSV+"\"private-value\n")){var failure=assertThrows(IllegalArgumentException.class,()->file(invalid));assertFalse(failure.getMessage().contains("private-value"));}}
    @Test void csvSupportsBomCrlfAndEscapedQuotedNotes()throws Exception{var data=file("\ufeff"+CSV.replace("synthetic Friday","\"synthetic, \"\"reviewed\"\"\"").replace("\n","\r\n"));assertEquals("synthetic, \"reviewed\"",data.days().getFirst().note());assertEquals(64,data.checksum().length());}
    @Test void sourceUrlsCannotStoreCredentialsOrQueryTokens()throws Exception{Path path=directory.resolve("source.csv");Files.writeString(path,CSV);for(String source:List.of("http://example.invalid/test.csv","https://user:private-value@example.invalid/test.csv","https://example.invalid/test.csv?token=private-value","https://example.invalid/test.csv#private-value")){var failure=assertThrows(IllegalArgumentException.class,()->ReviewedCalendar.read(path,"NSE","EQUITY",source));assertFalse(failure.getMessage().contains("private-value"));}}
    @Test void unsupportedExchangeAndSegmentAreRejected()throws Exception{Path path=directory.resolve("source.csv");Files.writeString(path,CSV);assertThrows(IllegalArgumentException.class,()->ReviewedCalendar.read(path,"FOREIGN","EQUITY","https://example.invalid/calendar.csv"));assertThrows(IllegalArgumentException.class,()->ReviewedCalendar.read(path,"NSE","UNKNOWN","https://example.invalid/calendar.csv"));}
    @Test void importedRowsAreImmutableSnapshots()throws Exception{var data=file(CSV);assertThrows(UnsupportedOperationException.class,()->data.days().clear());activate(data);assertEquals(data.checksum(),calendar.coverage("NSE","EQUITY").orElseThrow().checksum());}
    @Test void reviewReasonIsRequiredBeforeAnyDatabaseWrite()throws Exception{var data=file(CSV);assertThrows(IllegalArgumentException.class,()->tx.execute(status->calendar.activate(data,"OPERATOR_CLI","")));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM settlement_calendar_versions",Integer.class));}
    @Test void cliCannotImportWithoutAnExplicitReviewedMode(){String[] base={"--file","fixture.csv","--exchange","NSE","--segment","EQUITY","--source","https://example.invalid/calendar.csv"};assertThrows(IllegalArgumentException.class,()->CalendarImport.options(base));var args=new ArrayList<>(Arrays.asList(base));args.add("--validate");assertTrue(CalendarImport.options(args.toArray(String[]::new)).containsKey("--validate"));args.add("--reviewed");assertThrows(IllegalArgumentException.class,()->CalendarImport.options(args.toArray(String[]::new)));}
    @Test void duplicateOrUnknownCliOptionsAreRejected(){assertThrows(IllegalArgumentException.class,()->CalendarImport.options(new String[]{"--file","a","--file","b"}));assertThrows(IllegalArgumentException.class,()->CalendarImport.options(new String[]{"--unknown"}));}
}
